  reg [1:0] next_state;
  reg [1:0] next_walk_left;
  reg [1:0] next_walk_right;
  always @(posedge clk) begin
    if (areset) begin
      state <= 0;
    end else begin
      state <= next_state;
    end
  end
  always @(state, bump_left, bump_right) begin
    next_state <= state;
    next_walk_left <= walk_left;
    next_walk_right <= walk_right;
    case (state)
      0: begin
        if (bump_left) begin
          next_state <= 1;
          next_walk_left <= 1;
          next_walk_right <= 0;
        end
        else if (bump_right) begin
          next_state <= 2;
          next_walk_left <= 0;
          next_walk_right <= 1;
        end
        else begin
          next_state <= 0;
          next_walk_left <= 1;
          next_walk_right <= 1;
        end
      end
      1: begin
        if (bump_left) begin
          next_state <= 0;
          next_walk_left <= 0;
          next_walk_right <= 1;
        end
        else if (bump_right) begin
          next_state <= 2;
          next_walk_left <= 1;
          next_walk_right <= 0;
        end
        else begin
          next_state <= 1;
          next_walk_left <= 0;
          next_walk_right <= 0;
        end
      end
      2: begin
        if (bump_left) begin
          next_state <= 1;
          next_walk_left <= 1;
          next_walk_right <= 0;
        end
        else if (bump_right) begin
          next_state <= 0;
          next_walk_left <= 0;
          next_walk_right <= 1;
        end
        else begin
          next_state <= 2;
          next_walk_left <= 0;
          next_walk_right <= 0;
        end
      end
      default: begin
        next_state <= 0;
        next_walk_left <= 1;
        next_walk_right <= 1;
