module baud_gen (
    input clk, rst,
    input [7:0] div,
    output tick
);
reg [7:0] counter;
    reg tick_reg;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            tick_reg <= 0;
        end else begin
            if (counter == div - 1) begin
                counter <= 0;
                tick_reg <= 1;
            end else begin
                counter <= counter + 1;
                tick_reg <= 0;
            end
        end
    end

    assign tick = tick_reg;

endmodule

