module fifo_simple
#(
    parameter               WIDTH=16,
    parameter               DEPTH=16,
    parameter               PROG_FULL=14
)    
(
    input   wire                    reset_p,    
    input   wire                    clk,        

    input   wire    [WIDTH-1:0]     data_i,
    input   wire                    data_we,

    output  wire    [WIDTH-1:0]     data_o,
    input   wire                    data_rd,

    output  wire                    prog_full,
    output  wire                    full,
    output  wire                    empty,
    output  reg                     overflow,
    output  reg                     underflow

);
reg [WIDTH-1:0]    mem [0:DEPTH-1];
reg                 wr_ptr;
reg                 rd_ptr;
reg                 wr_en;
reg                 rd_en;
reg                 full;
reg                 empty;
reg                 prog_full;
reg                 overflow;
reg                 underflow;

wire                 full_p;
wire                 empty_p;
wire                 prog_full_p;
wire                 overflow_p;
wire                 underflow_p;

assign full_p = (wr_ptr == rd_ptr);
assign empty_p = (wr_ptr == rd_ptr);
assign prog_full_p = (wr_ptr == rd_ptr) && (wr_en == 1'b1);
assign overflow_p = (wr_ptr == rd_ptr) && (wr_en == 1'b1) && (data_we == 1'b1);
assign underflow_p = (wr_ptr == rd_ptr) && (wr_en == 1'b1) && (data_we == 1'b0);

assign full = full_p;
assign empty = empty_p;
assign prog_full = prog_full_p;
assign overflow = overflow_p;
assign underflow = underflow_p;

assign data_o = mem[rd_ptr];

always @(posedge clk) begin
    if (reset_p) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        wr_en <= 0;
        rd_en <= 0;
        overflow <= 0;
        underflow <= 0;
    end else begin
        if (wr_en && !full_p) begin
            mem[wr_ptr] <= data_i;
            wr_ptr <= wr_ptr + 1;
            if (wr_ptr == DEPTH-1) begin
                wr_ptr <= 0;
            end
        end
        if (rd_en && !empty_p) begin
            rd_ptr <= rd_ptr + 1;
            if (rd_ptr == DEPTH-1) begin
                rd_ptr <= 0;
            end
        end
        if (wr_en && data_we && full_p) begin
            overflow <= 1;
        end
        if (wr_en && !data_we && full_p) begin
            overflow <= 0;
        end
        if (rd_en && !data_rd && empty_p) begin
            underflow <= 1;
        end
        if (rd_en && data_rd && empty_p) begin
            underflow <= 0;
        end
    end
end

endmodule

module submulor_2_stage_unsigned_10_bit(
