module fifo36_demux
  #(parameter match_data = 0,
    parameter match_mask = 0)
   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);
localparam IDLE = 0, DATA0 = 1, DATA1 = 2;
reg [1:0] state = IDLE;
reg [35:0] data0_o, data1_o;
reg src0_rdy_o, src1_rdy_o;
reg eof;
assign dst_rdy_o = (state == DATA0 && dst0_rdy_i) || (state == DATA1 && dst1_rdy_i);
assign src0_rdy_o = state == DATA0;
assign src1_rdy_o = state == DATA1;
always @(posedge clk) begin
  if (clear) begin
    state <= IDLE;
    data0_o <= 0;
    data1_o <= 0;
  end else if (reset) begin
    state <= IDLE;
    data0_o <= 0;
    data1_o <= 0;
  end else begin
    case (state)
      IDLE: begin
        if (src_rdy_i && data_i[35:0] == match_data && data_i[35:0] == match_mask) begin
          state <= DATA0;
          data0_o <= data_i;
        end
        else if (src_rdy_i && data_i[35:0] == match_data && data_i[35:0] != match_mask) begin
          state <= DATA1;
          data1_o <= data_i;
        end
      end
      DATA0: begin
        if (src_rdy_i && data_i[35:0] == match_data && data_i[35:0] == match_mask) begin
          state <= DATA0;
          data0_o <= data_i;
        end
        else if (src_rdy_i && data_i[35:0] == match_data && data_i[35:0] != match_mask) begin
          state <= IDLE;
          data0_o <= 0;
        end
        else if (src_rdy_i && data_i[35:0] != match_data) begin
          state <= IDLE;
          data0_o <= 0;
        end
        else if (src_rdy_i && data_i[35:0] == match_data && data_i[35:0] != match_mask && eof) begin
          state <= IDLE;
          data0_o <= 0;
        end
      end
      DATA1: begin
        if (src_rdy_i && data_i[35:0] == match_data && data_i[35:0] == match_mask) begin
          state <= DATA1;
          data1_o <= data_i;
        end
        else if (src_rdy_i && data_i[35:0] == match_data && data_i[35:0] != match_mask) begin
          state <= IDLE;
          data1_o <= 0;
        end
        else if (src_rdy_i && data_i[35:0] != match_data) begin
          state <= IDLE;
          data1_o <= 0;
        end
        else if (src_rdy_i && data_i[35:0] == match_data && data_i[35:0] != match_mask && eof) begin
          state <= IDLE;
          data1_o <= 0;
        end
      end
      default: begin
        state <= IDLE;
        data0_o <= 0;
        data1_o <= 0;
      end
    endcase
  end
end
endmodule

module branch_ctrl(
