module UARTTransmitter(
  input        clock,
               reset,
               io_valid,
  input  [7:0] io_bits,
  input        tick,
  output       io_ready,
               tx
);
reg [3:0] state;
reg [7:0] data;
assign io_ready = (state == 4'b0000);
assign tx = state == 4'b0001 ? data[0] : 1'b0;
always @(posedge clock) begin
  if (reset) begin
    state <= 4'b0000;
    data <= 8'b00000000;
  end else if (tick) begin
    case (state)
      4'b0000: begin
        if (io_valid) begin
          data <= io_bits;
          state <= 4'b0001;
        end
      end
      4'b0001: begin
        data <= data >> 1;
        state <= 4'b0010;
      end
      4'b0010: begin
        state <= 4'b0011;
      end
      4'b0011: begin
        state <= 4'b0100;
      end
      4'b0100: begin
        state <= 4'b0101;
      end
      4'b0101: begin
        state <= 4'b0110;
      end
      4'b0110: begin
        state <= 4'b0111;
