module toe_m_axis_rxread_cmd_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b00,
    ONE  = 2'b01,
    TWO  = 2'b10;

reg [N-1:0] data_p1;
reg [N-1:0] data_p2;
reg [1:0] state_p1;
reg [1:0] state_p2;

reg load_p1;
reg load_p2;
reg load_p1_from_p2;

assign s_ready = state_p1 == ZERO;
assign m_valid = state_p2 == TWO;

always @(posedge clk) begin
    if (reset) begin
        data_p1 <= {N{1'b0}};
        data_p2 <= {N{1'b0}};
        state_p1 <= ZERO;
        state_p2 <= ZERO;
        load_p1 <= 1'b0;
        load_p2 <= 1'b0;
        load_p1_from_p2 <= 1'b0;
    end else begin
        if (s_valid && m_ready) begin
            if (state_p1 == ZERO) begin
                data_p1 <= s_data;
                state_p1 <= ONE;
            end
            else if (state_p1 == ONE) begin
                data_p2 <= s_data;
                state_p1 <= TWO;
            end
        end
        else if (m_valid && s_ready) begin
            if (state_p2 == ZERO) begin
                data_p1 <= data_p2;
                state_p2 <= ONE;
            end
            else if (state_p2 == ONE) begin
                data_p1 <= data_p2;
                state_p2 <= TWO;
            end
        end
        else if (load_p1) begin
            data_p1 <= s_data;
            state_p1 <= ONE;
        end
        else if (load_p2) begin
            data_p1 <= data_p2;
            state_p1 <= TWO;
        end
        else if (load_p1_from_p2) begin
            data_p1 <= data_p2;
            state_p1 <= ONE;
        end
        if (load_p1) load_p1 <= 1'b0;
        if (load_p2) load_p2 <= 1'b0;
        if (load_p1_from_p2) load_p1_from_p2 <= 1'b0;
    end
end

assign m_data = data_p1;
assign load_p1 = s_valid && m_ready;
assign load_p2 = m_valid && s_ready;
assign load_p1_from_p2 = state_p2 == ONE;

endmodule

