module Mapper66(input clk, input ce, input reset,
                input [31:0] flags,
                input [15:0] prg_ain, output [21:0] prg_aout,
                input prg_read, prg_write,                   
                input [7:0] prg_din,
                output prg_allow,                            
                input [13:0] chr_ain, output [21:0] chr_aout,
                output chr_allow,                      
                output vram_a10,                             
                output vram_ce);
reg [3:0] prg_bank, chr_bank;
reg [21:0] prg_aout, chr_aout;
reg vram_ce, vram_a10;
reg prg_allow, chr_allow;

always @(posedge clk) begin
    if (reset) begin
        prg_bank <= 4'b0000;
        chr_bank <= 4'b0000;
        vram_ce <= 0;
        vram_a10 <= 0;
        prg_allow <= 0;
        chr_allow <= 0;
    end else begin
        if (prg_write) begin
            if (prg_ain[15:13] == 3'b000) begin
                prg_bank <= prg_din;
            end
            if (prg_ain[15:13] == 3'b001) begin
                chr_bank <= prg_din;
            end
        end
        if (prg_read) begin
            if (prg_ain[15:13] == 3'b000) begin
                prg_aout <= prg_bank[3:0] + prg_ain[12:0];
            end
            if (prg_ain[15:13] == 3'b001) begin
                chr_aout <= chr_bank[3:0] + chr_ain[12:0];
            end
        end
        if (flags[15] == 1'b1) begin
            vram_ce <= 1;
            vram_a10 <= 1;
        end
        if (flags[15] == 1'b0) begin
            vram_ce <= 0;
            vram_a10 <= 0;
        end
        if (flags[14] == 1'b1) begin
            prg_allow <= 1;
            chr_allow <= 1;
        end
        if (flags[14] == 1'b0) begin
            prg_allow <= 0;
            chr_allow <= 0;
        end
    end
end

endmodule

