module udpLoopback_lbRxMetadataIn_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b00,
    ONE  = 2'b01,
    TWO  = 2'b10;
reg [1:0] state;
reg [N-1:0] data_p1, data_p2;
wire [N-1:0] data_p1_next, data_p2_next;
wire s_valid_next, s_ready_next;
wire m_valid_next, m_ready_next;
wire [N-1:0] m_data_next;
assign s_ready = (state == ZERO) || (state == ONE);
assign m_valid = (state == TWO) && m_ready;
assign m_data = (state == TWO) ? data_p2 : data_p1;
always @(posedge clk) begin
    if (reset) begin
        state <= ZERO;
        data_p1 <= {N{1'b0}};
        data_p2 <= {N{1'b0}};
    end else begin
        state <= state_next;
        data_p1 <= data_p1_next;
        data_p2 <= data_p2_next;
    end
end
always @(*) begin
    s_valid_next = s_valid;
    s_ready_next = s_ready;
    m_valid_next = m_valid;
    m_ready_next = m_ready;
    data_p1_next = data_p1;
    data_p2_next = data_p2;
    case (state)
        ZERO: begin
            if (s_valid) begin
                s_valid_next = 1'b0;
                s_ready_next = 1'b0;
                data_p1_next = s_data;
                data_p2_next = {N{1'b0}};
                state_next = ONE;
            end
        end
        ONE: begin
            if (s_valid) begin
                s_valid_next = 1'b0;
                s_ready_next = 1'b0;
                data_p1_next = s_data;
                data_p2_next = {N{1'b0}};
                state_next = TWO;
            end
            else if (s_ready) begin
                s_valid_next = 1'b1;
                s_ready_next = 1'b1;
                data_p1_next = data_p1;
                data_p2_next = data_p2;
                state_next = ZERO;
            end
        end
        TWO: begin
            if (s_valid) begin
                s_valid_next = 1'b0;
                s_ready_next = 1'b0;
                data_p1_next = s_data;
                data_p2_next = {N{1'b0}};
                state_next = ONE;
            end
            else if (s_ready) begin
                s_valid_next = 1'b1;
                s_ready_next = 1'b1;
                data_p1_next = data_p1;
                data_p2_next = data_p2;
                state_next = TWO;
            end
        end
        default: begin
            s_valid_next = 1'b0;
            s_ready_next = 1'b0;
            data_p1_next = {N{1'b0}};
            data_p2_next = {N{1'b0}};
            state_next = ZERO;
        end
    endcase
end
endmodule

