module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);
reg [BITS - 1:0] cnt;
    wire [BITS - 1:0] enable_wires;
    assign enable_wires = {ena, enable_wires};
    assign out = cnt;
    assign ovf = (cnt == 2**BITS - 1) ^ updown;
    genvar i;
    generate for (i = 0; i < BITS; i = i + 1) begin: gen
        always @(posedge clk, posedge rst) begin
            if (rst) begin
                cnt <= 0;
            end else if (ena) begin
                if (updown) begin
                    cnt <= cnt + 1;
                end else begin
                    cnt <= cnt - 1;
                end
            end
        end
    end
    endgenerate
endmodule

module BCD(
		input [15:0] binary,
		output wire [3:0] b,
		output wire [3:0] s,
		output wire [3:0] g,
		output wire [3:0] q
		);
reg [31:0] reg1;
	always @ (reg1) begin
		for (int i = 0; i < 16; i = i + 1) begin
			if (reg1[3*i+3:3*i] > 4) begin
				reg1[3*i+3:3*i] = reg1[3*i+3:3*i] + 3;
			end
		end
		reg1 = reg1 >> 4;
		end
	assign b = reg1[31:28];
	assign s = reg1[27:24];
	assign g = reg1[23:20];
	assign q = reg1[19:16];
endmodule

