module IB_ENDPOINT_OP_DONE_BUFFER(
input wire CLK,
input wire RESET,
input wire [15:0] RD_COMPL_TAG,
input wire RD_COMPL_START,
input wire RD_COMPL_DONE,
input wire [15:0] BM_TAG,
input wire BM_DONE,
output wire [15:0] OP_TAG,
output wire OP_DONE
); 

reg [15:0] rd_compl_tag;
reg rd_compl_start;
reg rd_compl_done;
reg bm_tag_valid;
reg bm_tag_ready;
reg [15:0] bm_tag;
reg [15:0] op_tag;
reg op_done;
  always @(posedge CLK, posedge RESET) begin
    if(RESET == 1'b1) begin
      rd_compl_tag <= 16'h0000;
      rd_compl_start <= 1'b0;
      rd_compl_done <= 1'b0;
      bm_tag_valid <= 1'b0;
      bm_tag_ready <= 1'b0;
      bm_tag <= 16'h0000;
      op_tag <= 16'h0000;
      op_done <= 1'b0;
    end else begin
      if(RD_COMPL_START == 1'b1) begin
        rd_compl_start <= 1'b1;
      end
      if(RD_COMPL_DONE == 1'b1) begin
        rd_compl_done <= 1'b1;
      end
      if(RD_COMPL_DONE == 1'b1 && rd_compl_start == 1'b1) begin
        rd_compl_start <= 1'b0;
        rd_compl_done <= 1'b0;
        rd_compl_tag <= RD_COMPL_TAG;
      end
      if(BM_DONE == 1'b1) begin
        bm_tag_valid <= 1'b1;
        bm_tag_ready <= 1'b1;
      end
      if(bm_tag_ready == 1'b1 && bm_tag_valid == 1'b1) begin
        bm_tag_ready <= 1'b0;
        bm_tag_valid <= 1'b0;
        bm_tag <= BM_TAG;
      end
      if(bm_tag_ready == 1'b1 && bm_tag_valid == 1'b1) begin
        op_tag <= bm_tag;
        op_done <= 1'b1;
      end
      if(bm_tag_ready == 1'b0 && bm_tag_valid == 1'b0) begin
        op_tag <= rd_compl_tag;
        op_done <= 1'b0;
      end
    end
  end
endmodule

