        else
            ReadData1 <= 0;
        if (ReadReg2 != 0)
            ReadData2 <= RegFile[ReadReg2];
        else
            ReadData2 <= 0;
    end
    always @(posedge Clk)
    begin
        if (RegWrite)
            RegFile[WriteReg] <= WriteData;
    end
endmodule

