  assign Qout[3] = (Q[3] ^ R[3]) & (Q[3] & R[3]);
  assign Qout[4] = (Q[4] ^ R[4]) & (Q[4] & R[4]);
  assign Qout[5] = (Q[5] ^ R[5]) & (Q[5] & R[5]);
  assign Qout[6] = (Q[6] ^ R[6]) & (Q[6] & R[6]);
