module DelayLoop(MR,Timeout,Clock) ;
input			MR, Clock;
output reg	Timeout;
parameter		divider = 100000;
reg [26:0] counter;
always @ (posedge Clock)
begin
	if (MR)
		counter <= 0;
	else if (counter == divider)
		counter <= 0;
	else
		counter <= counter + 1;
end
always @ (posedge Clock)
begin
	if (MR)
		Timeout <= 0;
	else if (counter == divider)
		Timeout <= 1;
end
endmodule

module counter_ex3(
input wire clk,
input wire clr,
input wire cnten,
output wire [15:0] q
); 

reg [15:0] cnt;
  always @(posedge clk, posedge clr, posedge cnten) begin
    if(clr == 1'b1) begin
      cnt <= {16{1'b0}};
    end else begin
      if(cnten == 1'b1) begin
        if(cnt == 16'b1111111111111111) begin
          cnt <= {16{1'b0}};
        end
        else begin
          cnt <= cnt + 1;
        end
      end
    end
  end
  assign q = cnt;
endmodule

