module TopModule(
    clk,
    reset,
    data,
    start_shifting
);

reg [3:0] state;
reg [3:0] next_state;
reg [3:0] shift_reg;
reg [3:0] shift_reg_next;
reg start_shifting_next;

always @ (posedge clk)
begin
    if (reset)
    begin
        state <= 0;
        shift_reg <= 0;
        start_shifting <= 0;
    end
    else
    begin
        state <= next_state;
        shift_reg <= shift_reg_next;
        start_shifting <= start_shifting_next;
    end
end

always @ (state, shift_reg)
begin
    case (state)
        0: begin
            if (shift_reg == 4'b1101)
                next_state <= 1;
            else
                next_state <= 0;
        end
        1: begin
            if (shift_reg == 4'b1101)
                next_state <= 1;
            else
                next_state <= 0;
        end
        default: next_state <= 0;
    endcase
end

always @ (state, shift_reg)
begin
    case (state)
        0: begin
            shift_reg_next <= shift_reg;
            start_shifting_next <= 0;
        end
        1: begin
            shift_reg_next <= shift_reg + 1;
            start_shifting_next <= 0;
        end
        default: begin
            shift_reg_next <= shift_reg;
            start_shifting_next <= 1;
        end
    endcase
end

endmodule

