module TopModule(
    clk,
    areset,
    bump_left,
    bump_right,
    walk_left,
    walk_right
);

reg [1:0] state;
    reg [1:0] next_state;

    always @(posedge clk) begin
        if (areset) begin
            state <= 0;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        case (state)
            2'b00: begin
                if (bump_left) begin
                    next_state <= 2'b01;
                end else if (bump_right) begin
                    next_state <= 2'b10;
                end else begin
                    next_state <= 2'b00;
                end
            end
            2'b01: begin
                next_state <= 2'b10;
            end
            2'b10: begin
                next_state <= 2'b01;
            end
            default: begin
                next_state <= 2'b00;
            end
        endcase
    end

    assign walk_left = state[0];
    assign walk_right = state[1];

endmodule

module TopModule(
    clk,
    reset,
    in,
    done
);

reg [2:0] state;
reg [7:0] byte;
reg [7:0] byte2;
reg [7:0] byte3;

always @(posedge clk) begin
    if (reset) begin
        state <= 0;
        byte <= 0;
        byte2 <= 0;
        byte3 <= 0;
    end else begin
        case (state)
            0: begin
                if (in[3]) begin
                    state <= 1;
                    byte <= in;
                end
            end
            1: begin
                if (in[3]) begin
                    state <= 2;
                    byte2 <= in;
                end
            end
            2: begin
                if (in[3]) begin
                    state <= 3;
                    byte3 <= in;
                end
            end
            3: begin
                state <= 0;
                done <= 1;
            end
            default: begin
                state <= 0;
                done <= 0;
            end
        endcase
    end
end

endmodule

module top(x, y, z);
  wire or1, or2, and1, and2, xor1;

  A a1(x, y, or1);
  A a2(x, y, or2);
  B b1(x, y, and1);
  B b2(x, y, and2);
  OR or(xor1, or1, or2);
  AND and(xor1, and1, and2);
  XOR xor(xor1, xor1, z);

endmodule

module TopModule (
      input      cpu_overheated,
      output reg shut_off_computer,
      input      arrived,
      input      gas_tank_empty,
      output reg keep_driving
  );

      always @(*) begin
          if (cpu_overheated)
             shut_off_computer = 1;
      end

      always @(*) begin
          if (~arrived)
             keep_driving = ~gas_tank_empty;
      end

  endmodule

module TopModule(
    clk,
    x,
    y,
    Y0,
    z
);
reg [2:0] Y;
    always @(posedge clk) begin
        if (x == 0) begin
            case (y)
                3'b000: Y <= 3'b000;
                3'b001: Y <= 3'b001;
                3'b010: Y <= 3'b010;
                3'b011: Y <= 3'b001;
                3'b100: Y <= 3'b011;
            endcase
        end
        else begin
            case (y)
                3'b000: Y <= 3'b001;
                3'b001: Y <= 3'b100;
                3'b010: Y <= 3'b010;
                3'b011: Y <= 3'b001;
                3'b100: Y <= 3'b100;
            endcase
        end
    end
    assign Y0 = Y[0];
    assign z = Y[2];
endmodule

