module TopModule(
    clk,
    areset,
    bump_left,
    bump_right,
    ground,
    dig,
    walk_left,
    walk_right,
    aaah,
    digging
);

reg [1:0] state;
reg [1:0] next_state;

always @(posedge clk) begin
    if (arst) begin
        state <= 2'b00;
    end else begin
        state <= next_state;
    end
end

always @(*) begin
    case (state)
        2'b00: begin
            next_state = 2'b00;
            if (bump_left) begin
                next_state = 2'b01;
            end
            if (bump_right) begin
                next_state = 2'b10;
            end
            if (ground) begin
                next_state = 2'b00;
            end
        end
        2'b01: begin
            next_state = 2'b00;
            if (bump_left) begin
                next_state = 2'b10;
            end
            if (bump_right) begin
                next_state = 2'b01;
            end
            if (ground) begin
                next_state = 2'b00;
            end
        end
        2'b10: begin
            next_state = 2'b00;
            if (bump_left) begin
                next_state = 2'b10;
            end
            if (bump_right) begin
                next_state = 2'b01;
            end
            if (ground) begin
                next_state = 2'b00;
            end
        end
        default: begin
            next_state = 2'b00;
        end
    endcase
end

assign walk_left = state[0];
assign walk_right = state[1];
assign aaah = (ground == 0) && (dig == 0);
assign digging = (ground == 1) && (state[0] == 0) && (state[1] == 0) && (dig == 1);

endmodule

